package org.slavicmyths.verify;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.phys.*;
import net.neoforged.neoforge.gametest.*;
import org.slavicmyths.poloz.*;
import org.slavicmyths.mor.*;
@GameTestHolder("slavicmyths_poloz") @PrefixGameTestTemplate(false)
public final class PolozIntegrationTests {
 @GameTest(template="empty",timeoutTicks=40) public static void realRecipe(GameTestHelper t){var holder=t.getLevel().getRecipeManager().byKey(PolozContent.id("mor_horn")).orElseThrow();var recipe=(net.minecraft.world.item.crafting.ShapedRecipe)holder.value();var items=new ArrayList<ItemStack>();for(var item:new Item[]{PolozContent.EYE.get(),Items.GOLD_INGOT,PolozContent.HEART.get(),PolozContent.DUST.get(),Items.GOAT_HORN,PolozContent.DUST.get(),PolozContent.DUST.get(),PolozContent.DUST.get(),PolozContent.DUST.get()})items.add(new ItemStack(item));var input=net.minecraft.world.item.crafting.CraftingInput.of(3,3,items);t.assertTrue(recipe.matches(input,t.getLevel()),"real exact recipe");t.assertTrue(recipe.assemble(input,t.getLevel().registryAccess()).is(PolozContent.HORN.get()),"horn output");for(int i=0;i<9;i++){var broken=new ArrayList<>(items);broken.set(i,ItemStack.EMPTY);t.assertTrue(!recipe.matches(net.minecraft.world.item.crafting.CraftingInput.of(3,3,broken),t.getLevel()),"missing component "+i);}t.succeed();}
 @GameTest(template="empty",timeoutTicks=40) public static void higherLoot(GameTestHelper t){var w=t.getLevel();for(var type:List.of(org.slavicmyths.registry.ModEntities.LIKHO_ONE_EYED.get(),org.slavicmyths.registry.ModEntities.OVINNIK.get())){var m=(org.slavicmyths.entity.LandSpiritEntity)type.create(w);m.moveTo(t.absoluteVec(new Vec3(3,3,3)));var drops=new ArrayList<net.minecraft.world.entity.item.ItemEntity>();var ordinary=new net.neoforged.neoforge.event.entity.living.LivingDropsEvent(m,m.damageSources().generic(),drops,true);PolozEvents.loot(ordinary);t.assertTrue(drops.isEmpty(),"ordinary no higher loot");t.assertTrue(m.mor.apply(true),"higher transformation");PolozEvents.loot(ordinary);t.assertTrue(drops.size()==1&&drops.getFirst().getItem().is(type==org.slavicmyths.registry.ModEntities.OVINNIK.get()?PolozContent.HEART.get():PolozContent.EYE.get()),"higher loot");m.getPersistentData().putUUID("summonedByPolozUUID",UUID.randomUUID());var summoned=new net.neoforged.neoforge.event.entity.living.LivingDropsEvent(m,m.damageSources().generic(),drops,true);PolozEvents.loot(summoned);t.assertTrue(summoned.isCanceled(),"no minion drops");m.discard();}t.succeed();}
 @GameTest(template="empty",timeoutTicks=40) public static void containerOnce(GameTestHelper t){var w=t.getLevel();var b=PolozGameTests.boss(t);BlockPos pos=b.blockPosition().above();w.setBlockAndUpdate(pos,Blocks.CHEST.defaultBlockState());var chest=(net.minecraft.world.level.block.entity.ChestBlockEntity)w.getBlockEntity(pos);chest.setItem(0,new ItemStack(Items.DIAMOND,17));b.impact.sample(b);t.assertTrue(b.impact.breakSize()<=2048&&b.impact.conversionSize()<=2048,"bounded queues");for(int i=0;i<70;i++)b.impact.tick(b);int count=w.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(pos).inflate(4)).stream().filter(e->e.getItem().is(Items.DIAMOND)).mapToInt(e->e.getItem().getCount()).sum();t.assertTrue(count==17,"contents exactly once: "+count);t.assertTrue(w.getBlockEntity(pos)==null,"chest removed");b.discard();t.succeed();}
 @GameTest(template="empty",timeoutTicks=40) public static void griefRule(GameTestHelper t){var w=t.getLevel();var b=PolozGameTests.boss(t);BlockPos q=b.blockPosition().above();w.setBlockAndUpdate(q,Blocks.OAK_PLANKS.defaultBlockState());var rule=w.getGameRules().getRule(net.minecraft.world.level.GameRules.RULE_MOBGRIEFING);boolean before=rule.get();rule.set(false,w.getServer());try{b.impact.sample(b);b.impact.tick(b);t.assertTrue(w.getBlockState(q).is(Blocks.OAK_PLANKS),"grief rule preserves world");t.assertTrue(MorBlocks.convert(w,q,b)==MorBlocks.Result.BLOCKED_BY_EVENT,"conversion rule");}finally{rule.set(before,w.getServer());b.discard();}t.succeed();}
 @GameTest(template="empty",timeoutTicks=40) public static void parallelAttackers(GameTestHelper t){var b=PolozGameTests.boss(t);for(int i=0;i<4;i++){var z=new net.minecraft.world.entity.monster.Zombie(EntityType.ZOMBIE,t.getLevel());z.moveTo(b.parts[24].position());t.assertTrue(b.parts[24].hurt(z.damageSources().mobAttack(z),10),"distinct attacker "+i);}t.assertTrue(b.getHealth()==2940,"parallel damage without shared iframe");b.discard();t.succeed();}
}
